/**
 * Starts the EXPRESS-009 app on real ports so you can send requests by hand.
 *   http://localhost:3000  working catalog with products p1 … p8
 *   http://localhost:3001  catalog that always throws (the "database" is down)
 * Run: npm run dev:express:9   (restarts on every save)
 * Do not edit this file; write your solution in task9.ts.
 */
import type { Express, NextFunction, Request, Response } from "express";
import { createApp, type Product, type ProductCatalog } from "./task9";

const sampleProducts: Product[] = [
  { id: "p1", name: "Trail Shoes", category: "footwear", priceCents: 12999, rating: 4.6, inStock: true, tags: ["running", "outdoor"] },
  { id: "p2", name: "Road Shoes", category: "footwear", priceCents: 10999, rating: 4.2, inStock: false, tags: ["running"] },
  { id: "p3", name: "Rain Jacket", category: "apparel", priceCents: 8999, rating: 4.1, inStock: true, tags: ["outdoor", "waterproof"] },
  { id: "p4", name: "Wool Socks", category: "apparel", priceCents: 1499, rating: 4.6, inStock: true, tags: ["winter"] },
  { id: "p5", name: "Headlamp", category: "gear", priceCents: 3999, rating: 4.5, inStock: true, tags: ["camping", "night"] },
  { id: "p6", name: "Camping Stove", category: "gear", priceCents: 8999, rating: 4.3, inStock: false, tags: ["camping", "cooking"] },
  { id: "p7", name: "water bottle", category: "gear", priceCents: 1999, rating: 4.0, inStock: true, tags: ["hydration"] },
  { id: "p8", name: "Sleeping Bag", category: "Gear", priceCents: 15999, rating: 4.9, inStock: true, tags: ["camping", "winter"] },
];

const workingCatalog: ProductCatalog = {
  getAll: async () => sampleProducts,
};

const brokenCatalog: ProductCatalog = {
  getAll: async () => {
    throw new Error("connection refused: products-db.internal:5432");
  },
};

function start(app: Express, port: number, label: string) {
  // Runs only for errors your code does not handle itself: prints the full error
  // in this terminal and returns it in the response, so you can see what leaked.
  app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
    console.error(`\nUnhandled error on ${req.method} ${req.originalUrl} (port ${port})\n`, err);
    const message = err instanceof Error ? err.message : String(err);
    res.status(500).json({ unhandledError: message });
  });
  app.listen(port, () => console.log(`EXPRESS-009 ${label}: http://localhost:${port}`));
}

start(createApp({ catalog: workingCatalog }), 3000, "working catalog");
start(createApp({ catalog: brokenCatalog }), 3001, "broken catalog ");
console.log("Send requests from src/express/task9/requests.http");
